<?php
require_once __DIR__.'/../includes/database.php';require_once __DIR__.'/../includes/pro-subscriptions.php';
function hosted_ok($v,$why){if(!$v)throw new RuntimeException($why);}
$db=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);initialize_database($db);stock_query($db,"INSERT INTO users(name,email,password_hash,role) VALUES('Fixture','hosted@example.invalid','unused','usuario')");$remote=[];$posts=0;$config=['enabled'=>true,'seller'=>'123','buyer'=>'test_user_fixture@testuser.com','amount'=>10000,'url'=>'https://repotools-desarrollo.onrender.com','plan'=>'hosted-plan','hosted_enabled'=>false];$transport=function($method,$path,$body=null)use(&$remote,&$posts){if($path==='/users/me')return ['id'=>123,'tags'=>['test_user']];if($path==='/preapproval'&&$method==='POST'){$posts++;hosted_ok(!isset($body['card_token_id'])&&$body['status']==='pending','Hosted payment has no card data');return $remote=['id'=>'hosted-sub','collector_id'=>123,'init_point'=>'https://www.mercadopago.com.ar/subscriptions/checkout?preapproval_id=hosted-sub',...$body];}if($path==='/preapproval/hosted-sub')return $remote;throw new RuntimeException('Unexpected request');};try{(new ProSubscriptions($db,$config,$transport))->checkout(1,'',true);throw new RuntimeException('Disabled hosted should refuse');}catch(CatalogException $e){hosted_ok($e->status===503,'Hosted disabled by default');}hosted_ok($posts===0,'Disabled feature sends nothing');$config['hosted_enabled']=true;$service=new ProSubscriptions($db,$config,$transport);$url=$service->checkout(1,'',true);hosted_ok(str_contains($url,'preapproval_id=hosted-sub'),'Provider URL belongs to own verified subscription');hosted_ok($service->checkout(1)===$url&&$posts===1,'Resume pending checkout without requesting another card or creating twice');hosted_ok((int)$db->query('SELECT paid_until FROM pro_subscriptions')->fetchColumn()===0,'Redirect grants no access');echo "OK hosted checkout contract: disabled default, own reference, no card data, pending resume, no entitlement. Mock provider only.\n";

foreach(['cancelled','paused','pending'] as $terminal){
 stock_query($db,"INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,'usuario')",['Fixture',$terminal.'@example.invalid','unused']);$user=(int)$db->lastInsertId();$attempts=0;$resource=[];
 $t=function($method,$path,$body=null)use(&$resource,&$attempts,$terminal){if($path==='/users/me')return ['id'=>123,'tags'=>['test_user']];if($method==='POST'&&$path==='/preapproval'){$attempts++;return $resource=['id'=>'missing-'.$terminal,'collector_id'=>123,...$body,'status'=>$terminal];}if(str_starts_with($path,'/preapproval/'))return $resource;throw new RuntimeException('Unexpected request');};
 $svc=new ProSubscriptions($db,$config,$t);try{$svc->checkout($user,'',true);throw new RuntimeException('Missing link should fail');}catch(CatalogException $e){hosted_ok($e->status===($terminal==='pending'?503:409),'Useful error for provider state');hosted_ok(!str_contains($e->getMessage(),'No recibimos el enlace'),'No generic link error');}
 $saved=stock_query($db,'SELECT status,provider_id,paid_until FROM pro_subscriptions WHERE user_id=?',[$user])->fetch();hosted_ok($saved['status']===$terminal&&$saved['provider_id']==='missing-'.$terminal,'Verified state survives error response');hosted_ok((int)$saved['paid_until']===0,'Failure grants no access');if($terminal!=='pending'){try{$svc->checkout($user,'fixture_token_123456');}catch(CatalogException $e){hosted_ok($e->status===409,'Terminal attempt cannot create twice');}hosted_ok($attempts===1,'No duplicate POST');}
}
echo "OK missing checkout: cancelled/paused/pending saved without granting access or duplicate creation.\n";
